<?php require "api/comun.php"; $d=getDB(); foreach(["stock_sucursal","stock_sucursal_movimientos","stock_minimo_sucursal","ubicaciones"] as $t){ echo "\n=== $t ===\n"; foreach($d->query("DESCRIBE $t")->fetchAll(PDO::FETCH_ASSOC) as $r) echo "  ".$r["Field"].": ".$r["Type"]."\n"; } echo "\n=== ubicaciones DATA ===\n"; foreach($d->query("SELECT id, nombre FROM ubicaciones")->fetchAll(PDO::FETCH_ASSOC) as $r) echo "  {$r[id]}: {$r[nombre]}\n"; ?>
